def seed_quizzes(db: Session) -> None:
    """Insert the quiz bank into the existing database without duplicating rows."""
    existing_ids = {row[0] for row in db.query(QuizQuestion.id).all()}
    rows = [QuizQuestion(**q) for q in QUIZ_QUESTIONS if q["id"] not in existing_ids]
    if rows:
        db.add_all(rows)
        db.commit()

def get_quiz_questions(db: Session, experiment_id: str):
    return (
        db.query(QuizQuestion)
        .filter(QuizQuestion.experiment_id == experiment_id)
        .order_by(QuizQuestion.id)
        .all()
    )

def submit_quiz(db: Session, experiment_id: str, answers):
    questions = get_quiz_questions(db, experiment_id)
    if not questions:
        return None

    question_map = {q.id: q for q in questions}
    seen = set()
    correct = 0

    for answer in answers:
        if answer.question_id in seen:
            continue
        seen.add(answer.question_id)
        question = question_map.get(answer.question_id)
        if question and answer.answer.upper() == question.correct_answer.upper():
            correct += 1

    total = len(questions)
    score = round(correct / total * 100)
    return {
        "score": score,
        "total_questions": total,
        "correct_answers": correct,
        "passed": score >= PASSING_SCORE,
    }
